//! The approved BN254 predicate circuits compiled into this crate (see `approved.rs`, generated by
//! `scripts/groth16_setup.py`). A bundled artifact is only used if its bytes still hash to the
//! recorded identity.

use sha2::{Digest, Sha256};

use crate::{approved::BUNDLED, Groth16Error, Result};

pub(crate) struct Bundled {
    pub name: &'static str,
    pub r1cs: &'static [u8],
    pub sym: &'static str,
    pub zkey: &'static [u8],
    pub r1cs_sha256: &'static str,
    pub zkey_sha256: &'static str,
}

fn hex_sha256(bytes: &[u8]) -> String {
    Sha256::digest(bytes)
        .iter()
        .map(|b| format!("{b:02x}"))
        .collect()
}

/// The approved artifacts of circuit `name`.
pub(crate) fn approved(name: &str) -> Result<&'static Bundled> {
    BUNDLED
        .iter()
        .find(|b| b.name == name)
        .filter(|b| hex_sha256(b.r1cs) == b.r1cs_sha256 && hex_sha256(b.zkey) == b.zkey_sha256)
        .ok_or_else(|| Groth16Error::Unapproved(name.into()))
}

/// Names of every bundled circuit.
pub fn circuits() -> impl Iterator<Item = &'static str> {
    BUNDLED.iter().map(|b| b.name)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_bundled_artifact_matches_its_recorded_identity() {
        for name in circuits() {
            assert!(approved(name).is_ok(), "{name}");
        }
        assert_eq!(circuits().count(), 12);
        assert!(approved("nope").is_err());
    }
}
